create function public.pitacco_pagbank_sandbox_catalog(p_store uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare slug text; begin if not exists(select 1 from pitacco_private.pagbank_sandbox_accounts where store_id=p_store) or not exists(select 1 from pitacco_private.ifood_merchants where store_id=p_store and test_only) then raise exception 'Somente loja vinculada de homologação'; end if; select m.slug into slug from public.public_menu_settings m where m.store_id=p_store and m.enabled; if slug is null then raise exception 'Cardápio indisponível'; end if; return public.get_public_menu(slug); end $$; revoke all on function public.pitacco_pagbank_sandbox_catalog(uuid) from public,anon,authenticated; grant execute on function public.pitacco_pagbank_sandbox_catalog(uuid) to service_role;